#include "commerce_details.hpp"
#include <iostream>
int main(){using namespace perekup;std::string line;while(std::getline(std::cin,line)){try{auto q=Json::parse(line);const auto offer=q.at("offer"),car=q.at("car");Json offers={{offer.at("id").get<std::string>(),offer}},cars={{std::to_string(car.at("id").get<Money>()),car}},cities={{"home",{{"id","home"},{"name","Москва"}}}};Json s={{"gameMs",1000000},{"balance",1000000},{"transport",{{"cityId",q.value("away",false)?"away":"home"},{"trip",q.value("travelling",false)?Json::object():Json(nullptr)}}},{"commerce",freshCommerce()}};if(q.contains("order")&&q["order"].is_object())s["commerce"]["orders"].push_back(q["order"]);auto target=q.contains("order")&&q["order"].is_object()?q["order"].at("id").get<std::string>():offer.at("id").get<std::string>();Json results=Json::array();for(const auto& step:q.at("steps")){s["gameMs"]=step.value("now",1000000LL);auto r=askNativeCommerceQuestion(s,offer.at("kind"),target,step.at("topic"),offers,cars,cities,"home",[](Money n){return std::to_string(n)+" RUB";},[](Money n){return std::to_string(n)+" DATE";},[](const Json&){});results.push_back(r.ok);}std::cout<<Json{{"results",results},{"dialogues",s["commerce"]["dialogues"]},{"revision",s["commerce"]["revision"]},{"balance",s["balance"]},{"now",s["gameMs"]}}.dump()<<'\n';}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}}
